import os
import re

file_path = "storage/progressor/raw_eval_logs/raw_exec_log_eval_489.txt"

print(f"Attempting to read and verify content from: {file_path}")

if not os.path.exists(file_path):
    print(f"Error: File not found at {file_path}. Delivery may not be complete.")
else:
    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            raw_log_content = f.read()

        print(f"\n--- Snippet of raw_exec_log_eval_489.txt (first 2500 chars) ---")
        print(raw_log_content[:2500])
        print("--- End of Snippet ---")

        # Check for both the sandbox execution header and strategy pattern
        if "PYTHON SANDBOX EXECUTION:" in raw_log_content and re.search(r"action_strategy = defaultdict\((<function <lambda> at 0x[0-9a-fA-F]+>|@)", raw_log_content, re.DOTALL):
            print("\nVerification successful: File contains complete raw execution log with agent strategies. Ready for extraction.")
        else:
            print("\nVerification failed: File does NOT appear to contain complete raw execution log or agent strategies in the expected format.")
    except Exception as e:
        print(f"An unexpected error occurred during file reading or verification: {e}")
